extern "C" fn my_callback(data: *const Unit) -> Int {
  return 42;
}

extern "C" {
  fn register(cb: extern "C" fn(*const Unit) -> Int) -> Unit;
}

fn main() -> Int {
  unsafe {
    register(my_callback);
  }
  return 0;
}
